async def act(page):
    """
    Perform a visible search for 'crypto' using the site-aware helper and click
    the third-to-last search result. Robustly dismisses obvious overlays first.

    Key fixes vs previous attempts:
    - Locator variables are always set to Playwright Locator objects (never None),
      so .nth() is never called on None.
    - Every .nth() usage is preceded by an awaited .count() to avoid indexing errors.
    - Uses the provided create_curated_collection_by_search(...) helper to run the
      visible search as required.
    """
    import asyncio

    async def dismiss_overlay():
        """Attempt several safe, accessibility-role-centric strategies to close
        visible overlays/popups. Returns True if an attempt was likely executed,
        False otherwise. All locator variables remain Locator objects.
        """
        # 1) Dialog-based approach
        dialogs = page.get_by_role("dialog")
        try:
            dialog_count = await dialogs.count()
        except Exception:
            dialog_count = 0

        close_names = ["close", "dismiss", "ok", "×", "x", "✕", "close popup", "dismiss popup", "close window"]
        for i in range(dialog_count):
            dlg = dialogs.nth(i)
            # Try named buttons inside the dialog
            for name in close_names:
                btn = dlg.get_by_role("button", name=name)
                try:
                    btn_count = await btn.count()
                except Exception:
                    btn_count = 0
                if btn_count > 0:
                    try:
                        await btn.nth(0).click()
                        await page.wait_for_timeout(300)
                        return True
                    except Exception:
                        pass

            # Fallback: click the first button inside the dialog
            inner_buttons = dlg.get_by_role("button")
            try:
                inner_btn_count = await inner_buttons.count()
            except Exception:
                inner_btn_count = 0
            if inner_btn_count > 0:
                try:
                    await inner_buttons.nth(0).click()
                    await page.wait_for_timeout(300)
                    return True
                except Exception:
                    pass

        # 2) Top-level buttons that likely close overlays
        all_buttons = page.get_by_role("button")
        try:
            all_btn_count = await all_buttons.count()
        except Exception:
            all_btn_count = 0

        for i in range(all_btn_count):
            btn = all_buttons.nth(i)
            try:
                aria = await btn.get_attribute("aria-label") or ""
            except Exception:
                aria = ""
            try:
                title = await btn.get_attribute("title") or ""
            except Exception:
                title = ""
            try:
                txt = await btn.inner_text() or ""
            except Exception:
                txt = ""

            aria_l = aria.lower() if isinstance(aria, str) else ""
            title_l = title.lower() if isinstance(title, str) else ""
            txt_l = txt.strip().lower() if isinstance(txt, str) else ""

            if ("close" in aria_l) or ("close" in title_l) or ("close" in txt_l) or (txt.strip() in ["×", "x", "✕"]):
                try:
                    await btn.click()
                    await page.wait_for_timeout(300)
                    return True
                except Exception:
                    pass

        # 3) Named dismiss button
        dismiss_btn = page.get_by_role("button", name="dismiss")
        try:
            dismiss_count = await dismiss_btn.count()
        except Exception:
            dismiss_count = 0
        if dismiss_count > 0:
            try:
                await dismiss_btn.nth(0).click()
                await page.wait_for_timeout(300)
                return True
            except Exception:
                pass

        # 4) CSS fallbacks for common close affordances
        css_candidates = page.locator('[aria-label*="close" i],[title*="close" i],.close,button.close,.modal-close,.popup-close')
        try:
            css_count = await css_candidates.count()
        except Exception:
            css_count = 0
        if css_count > 0:
            try:
                await css_candidates.nth(0).click()
                await page.wait_for_timeout(300)
                return True
            except Exception:
                pass

        return False

    # Best-effort dismiss overlay before calling the helper (helper itself does goto('/')).
    try:
        await dismiss_overlay()
    except Exception:
        # ignore dismissal errors and proceed to helper which resets to '/'
        pass

    # Use the required site-aware helper to perform the visible search for 'crypto'.
    try:
        results = await create_curated_collection_by_search(page, "crypto", max_results=0, resolve_links=True)
    except Exception:
        results = []

    # Print the raw helper results exactly as returned (requirement when using API/helper).
    print(results)

    # If no results (overlay may have blocked the complementary region), try dismissing and retry once.
    if not results:
        try:
            await dismiss_overlay()
        except Exception:
            pass
        try:
            results = await create_curated_collection_by_search(page, "crypto", max_results=0, resolve_links=True)
        except Exception:
            results = []
        print(results)

    # Now attempt to click the third-to-last article in role="main" -> role="article".
    main = page.get_by_role("main")
    articles = main.get_by_role("article")
    try:
        article_count = await articles.count()
    except Exception:
        article_count = 0

    if article_count < 3:
        raise Exception(f"Not enough search results to click the third-to-last (found {article_count}).")

    target_index = article_count - 3
    target_article = articles.nth(target_index)

    # Prefer clicking a link inside the article
    links = target_article.get_by_role("link")
    try:
        link_count = await links.count()
    except Exception:
        link_count = 0
    if link_count > 0:
        await links.nth(0).click()
        return

    # Fallback: click a heading inside the article
    headings = target_article.get_by_role("heading")
    try:
        heading_count = await headings.count()
    except Exception:
        heading_count = 0
    if heading_count > 0:
        await headings.nth(0).click()
        return

    # Final fallback: click the article container itself
    await target_article.click()
    return

